  {"term_id": "Aziz", "def_en": "A hadith narrated by at least two narrators at every level of the chain.", "id": "aziz", "term_en": "Aziz", "def_id": "Hadits yang diriwayatkan oleh setidaknya dua orang perawi pada setiap tingkatan sanadnya."},
  {"term_id": "Gharib", "def_en": "A hadith narrated by only one narrator at some level in its chain.", "id": "gharib", "term_en": "Gharib", "def_id": "Hadits yang hanya diriwayatkan oleh satu orang perawi pada suatu tingkatan dalam sanadnya."},
