  {"term_id": "Atsar", "def_id": "Ucapan atau perbuatan yang disandarkan kepada selain Rasulullah SAW, yakni kepada para sahabat dan tabi'in.", "def_en": "Statements or actions attributed to someone other than the Prophet, typically the Companions (Sahabah) or Successors (Tabi'in).", "id": "atsar", "term_en": "Atsar"},
  {"term_id": "Marfu'", "def_id": "Suatu ucapan, perbuatan, atau persetujuan yang secara langsung disandarkan kepada Rasulullah SAW.", "def_en": "A statement, action, or approval directly attributed to the Prophet Muhammad.", "id": "marfu", "term_en": "Marfu'"},
