  {"term_id": "Jayyid", "def_id": "Bagus. Istilah lain yang sering digunakan oleh para ulama untuk menyebut hadits yang berderajat Shahih.", "def_en": "Good or excellent. Used by scholars as another term for a Sahih (authentic) hadith.", "id": "jayyid", "term_en": "Jayyid"},
  {"term_id": "Muhaddits", "def_id": "Ulama ahli hadits yang menyibukkan diri dengan ilmu riwayat dan dirayat (fikih hadits), serta banyak mengetahui keadaan para perawi.", "def_en": "A scholar of hadith who occupies themselves with the science of narration and hadith jurisprudence, and knows many narrators and their conditions.", "id": "muhaddits", "term_en": "Muhaddits"},
  {"term_id": "Al-Hafizh", "def_id": "Gelar bagi ulama hadits yang kedudukannya lebih tinggi dari muhaddits, yang lebih banyak mengetahui perawi di setiap tingkatan sanad daripada yang tidak ia ketahui.", "def_en": "A title for a hadith scholar of very high rank who knows more narrators in every level of the chain than those they do not know.", "id": "al_hafizh", "term_en": "Al-Hafizh"},
